/*<       character*16bnodid(mnbn) >*/
/* SOURCE bnothr.cmn:10 */
/*<        >*/
/* SOURCE bnothr.cmn:13 */
/*<        >*/
/*     Called program units */
/* SOURCE inputuf.for:4818 */
/*<       realget_slot_depth >*/
