/*      SUBROUTINE   PFIN */
/*     I                 (IN, STDOUT, MLPNT, NBRA, BRPT, */
/*     O                  EFLAG, LPNT, MF, PFPNT) */

/* C     + + + PURPOSE + + + */
/* C     Input the point load information. */

/*      IMPLICIT NONE */
/* C     + + + DUMMY ARGUMENTS + + + */
/*      INTEGER EFLAG, IN, STDOUT, LPNT, MLPNT, NBRA */
/*      INTEGER BRPT(8,NBRA), PFPNT(3,MLPNT) */
/*      REAL MF(MLPNT) */

/* C     + + +DUMMY ARGUMENT DEFINITIONS + + + */
/* C     IN     - unit number for the user input file */
/* C     STDOUT   - Fortran unit number for user output and messages */
/* C     MLPNT  - maximum length of the point load pointer arrays */
/* C     NBRA   - number of branches in the model */
/* C     BRPT   - branch pointer table.  Values for each branch are: */
/* C              ROW       Meaning */
/* C              1         upstream user node number */
/* C              2         downstream user node number */
/* C              3         pointer into branch vector for upstream node */
/* C              4         pointer into branch vector for downstream node */
/* C              5         upstream exterior node number */
/* C              6         downstream exterior node number */
/* C              7         pointer to address in EMC for the branch */
/* C              8         number of unknowns at a node for the branch */
/* C     EFLAG  - flag for errors. 0- no errors, > 0 one or more errors */
/* C     LPNT   - length of the point load point load array */
/* C     MF     - momentum flux value */
/* C     PFPNT  - point flow pointer array */

/* C     + + + LOCAL VARIABLES + + + */
/*      INTEGER BRA, BRAIN, NODE, TABLE, TYPE */
/*      REAL MFAC */
/*      CHARACTER LINE*80, NODEIN*5, TABID*16 */

/* C     + + + EXTERNAL NAMES + + + */
/*      EXTERNAL GETINB, GETINN, inline, KIL, KILC, */
/*     A         STRIP_L_BLANKS, GET_INTERNAL_TAB_NUMBER */

/* C     + + + INPUT FORMATS + + + */
/* 35   FORMAT(I5,A5,I5,A16,F10.0) */

/* C     + + + OUTPUT FORMATS + + + */
/* 36   FORMAT(' ',I5,A5,I5,1X,A16,F10.5) */
/* C*********************************************************************** */
/*      LPNT = 1 */
/* 1000 CONTINUE */
/*         CALL inline */
/*     I             (IN, STDOUT, */
/*     O              LINE) */
/*         READ(LINE,35,ERR=991) BRAIN, NODEIN, TYPE, TABID, MFAC */
/*         IF(BRAIN.EQ.-1) GOTO 2000 */
/*         WRITE(STDOUT,36) BRAIN, NODEIN, TYPE, TABID, MFAC */
/*         CALL GETINB */
/*     M              (BRAIN, */
/*     O               EFLAG, BRA) */
/*          CALL GETINN */
/*     M               (NODEIN, */
/*     O                EFLAG, NODE) */
/*          CALL STRIP_L_BLANKS( */
/*     M                        TABID) */
/*          CALL GET_INTERNAL_TAB_NUMBER */
/*     I                                (STDOUT, TABID, */
/*     M                                 EFLAG, */
/*     O                                 TABLE) */

/*         IF(NODE.LT.BRPT(1,BRA).OR.NODE.GT.BRPT(2,BRA)) */
/*     1      CALL KILC */
/*     I                (NODEIN, -2, */
/*     M                 EFLAG) */
/*         IF(TYPE.LE.0.OR.TYPE.GT.2) CALL KIL */
/*     I                                       (18, */
/*     M                                        TYPE, EFLAG) */
/*         IF(NODE.EQ.BRPT(1,BRA)) CALL KILC */
/*     I                                     (NODEIN, -28, */
/*     M                                      EFLAG) */

/* C     TABLE IDS WILL BE CHECKED ELSEWHERE */

/*         IF(LPNT.GE.MLPNT) CALL KIL */
/*     I                              (19, */
/*     M                               LPNT, EFLAG) */
/*         PFPNT(1,LPNT) = TYPE */
